-- Additive reservation: no historical or business rows are rewritten.
CREATE TABLE IF NOT EXISTS offline_route_reservations(
 id TEXT PRIMARY KEY,device_id TEXT NOT NULL REFERENCES sync_devices(id),user_id TEXT NOT NULL REFERENCES users(id),
 route_id TEXT NOT NULL REFERENCES routes(id),session_id TEXT NOT NULL REFERENCES cash_sessions(id),day TEXT NOT NULL,
 created_at TEXT NOT NULL,released_at TEXT,payload TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('active','syncing','released')));
CREATE UNIQUE INDEX IF NOT EXISTS offline_route_one_active ON offline_route_reservations(route_id) WHERE state<>'released';
CREATE UNIQUE INDEX IF NOT EXISTS offline_device_one_active ON offline_route_reservations(device_id) WHERE state<>'released';
CREATE TRIGGER IF NOT EXISTS offline_stock_update BEFORE UPDATE ON route_stock WHEN EXISTS(SELECT 1 FROM offline_route_reservations WHERE route_id=OLD.route_id AND state='active') BEGIN SELECT RAISE(ABORT,'Sincroniza y finaliza el modo sin internet antes de modificar el inventario.'); END;
CREATE TRIGGER IF NOT EXISTS offline_stock_delete BEFORE DELETE ON route_stock WHEN EXISTS(SELECT 1 FROM offline_route_reservations WHERE route_id=OLD.route_id AND state='active') BEGIN SELECT RAISE(ABORT,'Hay inventario reservado sin internet.'); END;
CREATE TRIGGER IF NOT EXISTS offline_cash_close BEFORE UPDATE OF state ON cash_sessions WHEN NEW.state='closed' AND EXISTS(SELECT 1 FROM offline_route_reservations WHERE session_id=OLD.id AND state<>'released') BEGIN SELECT RAISE(ABORT,'Sincroniza y finaliza el modo sin internet antes de cerrar la caja.'); END;
CREATE TRIGGER IF NOT EXISTS offline_group_remove BEFORE DELETE ON product_groups WHEN EXISTS(SELECT 1 FROM offline_route_reservations r JOIN route_stock s ON s.route_id=r.route_id WHERE s.group_id=OLD.group_id AND r.state<>'released') BEGIN SELECT RAISE(ABORT,'El grupo tiene inventario reservado sin internet.'); END;
CREATE TRIGGER IF NOT EXISTS offline_product_status BEFORE UPDATE OF active ON products WHEN NEW.active<>OLD.active AND EXISTS(SELECT 1 FROM product_groups p JOIN route_stock s ON s.group_id=p.group_id JOIN offline_route_reservations r ON r.route_id=s.route_id WHERE p.product_id=OLD.id AND r.state<>'released') BEGIN SELECT RAISE(ABORT,'Finaliza el modo sin internet antes de desactivar productos reservados.'); END;
CREATE TRIGGER IF NOT EXISTS offline_customer_status BEFORE UPDATE OF active ON customers WHEN NEW.active<>OLD.active AND EXISTS(SELECT 1 FROM customer_routes c JOIN offline_route_reservations r ON r.route_id=c.route_id WHERE c.customer_id=OLD.id AND r.state<>'released') BEGIN SELECT RAISE(ABORT,'Finaliza el modo sin internet antes de desactivar clientes reservados.'); END;
CREATE TRIGGER IF NOT EXISTS offline_customer_route BEFORE DELETE ON customer_routes WHEN EXISTS(SELECT 1 FROM offline_route_reservations WHERE route_id=OLD.route_id AND state<>'released') BEGIN SELECT RAISE(ABORT,'Finaliza el modo sin internet antes de cambiar clientes de ruta.'); END;
CREATE TRIGGER IF NOT EXISTS offline_seller_route BEFORE UPDATE ON seller_routes WHEN EXISTS(SELECT 1 FROM offline_route_reservations WHERE user_id=OLD.user_id AND state<>'released') BEGIN SELECT RAISE(ABORT,'Finaliza el modo sin internet antes de cambiar la ruta del usuario.'); END;
CREATE TRIGGER IF NOT EXISTS offline_agent_status BEFORE UPDATE ON sales_agents WHEN EXISTS(SELECT 1 FROM offline_route_reservations WHERE user_id=OLD.user_id AND state<>'released') BEGIN SELECT RAISE(ABORT,'Finaliza el modo sin internet antes de cambiar los vendedores.'); END;
